package com.tourism.business.finance.service;
import com.tourism.business.finance.dto.FinanceDto.*;
import com.tourism.business.admissions.service.AdmissionService;
import com.tourism.business.availability.service.AvailabilityService;
import com.tourism.business.business.repository.SettingsRepository;
import com.tourism.business.common.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.ObjectMapper;
@Service
public class FinanceService {
    private final JdbcTemplate jdbc;private final SettingsRepository settings;private final AvailabilityService dates;private final CashSessionService cash;private final AdmissionService validation;private final IdempotencyStore keys;private final ObjectMapper mapper;private final Clock clock;
    public FinanceService(JdbcTemplate jdbc,SettingsRepository settings,AvailabilityService dates,CashSessionService cash,AdmissionService validation,IdempotencyStore keys,ObjectMapper mapper,Clock clock){this.jdbc=jdbc;this.settings=settings;this.dates=dates;this.cash=cash;this.validation=validation;this.keys=keys;this.mapper=mapper;this.clock=clock;}
    private BigDecimal amount(String value){var amount=new BigDecimal(value);if(amount.signum()<=0)throw new ApiException(400,"AMOUNT_POSITIVE");return amount.setScale(2);}
    private Map<String,Object> one(String sql,Object...args){var rows=jdbc.queryForList(sql,args);if(rows.isEmpty())throw new ApiException(404,"NOT_FOUND");return rows.getFirst();}
    private Map<String,Object> json(Map<String,Object> row){var result=new LinkedHashMap<String,Object>();row.forEach((k,v)->result.put(k,v instanceof BigDecimal n?n.toPlainString():v instanceof java.sql.Timestamp t?t.toLocalDateTime().toInstant(ZoneOffset.UTC).toString():v instanceof java.sql.Date d?d.toLocalDate().toString():v instanceof byte[] b?Base64.getEncoder().encodeToString(b):v!=null&&(k.equals("id")||k.endsWith("Id"))?v.toString():v));return result;}
    private List<Map<String,Object>> rows(String sql,Object...args){return jdbc.queryForList(sql,args).stream().map(this::json).toList();}
    private BigDecimal net(long id){return jdbc.queryForObject("SELECT COALESCE((SELECT SUM(amount) FROM dbo.Payment WHERE admissionId=?),0)+COALESCE((SELECT SUM(amount) FROM dbo.Adjustment WHERE admissionId=?),0)-COALESCE((SELECT SUM(amount) FROM dbo.Refund WHERE admissionId=?),0)",BigDecimal.class,id,id,id);}
    private void lockAdmission(long id){var a=one("SELECT a.id,d.visitDate FROM dbo.Admission a JOIN dbo.VisitDay d ON d.id=a.visitDayId WHERE a.id=?",id);dates.lockDay(LocalDate.parse(a.get("visitDate").toString()));one("SELECT id FROM dbo.Admission WITH(UPDLOCK,HOLDLOCK) WHERE id=?",id);}
    private void touch(long session){jdbc.update("UPDATE dbo.CashSession SET status=status WHERE id=?",session);}
    @Transactional(isolation=Isolation.SERIALIZABLE)
    public Map<String,Object> expense(Expense request,String key,long actor){validation.validate(request);settings.read(true,dates.today());String operation="EXPENSE:"+actor;var existing=keys.read(operation,key,request);if(existing!=null)return existing;long session=cash.lockCurrent();var amount=amount(request.amount());jdbc.update("INSERT dbo.Expense(cashSessionId,method,amount,category,description,actorId) VALUES(?,?,?,?,?,?)",session,request.method(),amount,request.category().trim(),request.description().trim(),actor);var result=json(one("SELECT TOP(1) * FROM dbo.Expense WHERE cashSessionId=? ORDER BY id DESC",session));touch(session);keys.save(operation,key,request,result);return result;}
    @Transactional(isolation=Isolation.SERIALIZABLE)
    public Map<String,Object> refund(Refund request,String key,long actor){validation.validate(request);settings.read(true,dates.today());String operation="REFUND:"+actor;var existing=keys.read(operation,key,request);if(existing!=null)return existing;lockAdmission(request.admissionId());long session=cash.lockCurrent();var amount=amount(request.amount());if(amount.compareTo(net(request.admissionId()))>0)throw new ApiException(409,"REFUND_EXCEEDS_NET");var payments=jdbc.queryForList("SELECT id FROM dbo.Payment WHERE admissionId=?",Long.class,request.admissionId());jdbc.update("INSERT dbo.Refund(admissionId,paymentId,cashSessionId,method,amount,reason,actorId) VALUES(?,?,?,?,?,?,?)",request.admissionId(),payments.isEmpty()?null:payments.getFirst(),session,request.method(),amount,request.reason().trim(),actor);var result=json(one("SELECT TOP(1) * FROM dbo.Refund WHERE cashSessionId=? ORDER BY id DESC",session));touch(session);keys.save(operation,key,request,result);return result;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public Map<String,Object> refundable(long admissionId){var admission=validation.detail(admissionId);return Map.of("id",admission.get("id"),"code",admission.get("code"),"visitDate",admission.get("visitDate"),"available",net(admissionId).toPlainString());}
    private Map<String,Object> compensationSource(Compensation request){String table=switch(request.sourceType()){case "EXPENSE"->"Expense";case "REFUND"->"Refund";default->"Adjustment";};var row=one("SELECT * FROM dbo."+table+" WHERE id=?",request.sourceId());String field=switch(request.sourceType()){case "EXPENSE"->"expenseId";case "REFUND"->"refundId";default->"originalAdjustmentId";};if(request.sourceType().equals("ADJUSTMENT")&&!jdbc.queryForList("SELECT id FROM dbo.Adjustment WHERE "+field+"=?",request.sourceId()).isEmpty())throw new ApiException(409,"ALREADY_COMPENSATED");return row;}
    private BigDecimal compensationAmount(Compensation request,Map<String,Object> source){var original=(BigDecimal)source.get("amount");if(request.sourceType().equals("ADJUSTMENT"))return original.negate();String field=request.sourceType().equals("EXPENSE")?"expenseId":"refundId";var previous=jdbc.queryForObject("WITH chain AS (SELECT id,amount FROM dbo.Adjustment WHERE "+field+"=? UNION ALL SELECT a.id,a.amount FROM dbo.Adjustment a JOIN chain c ON a.originalAdjustmentId=c.id) SELECT COALESCE(SUM(amount),0) FROM chain OPTION(MAXRECURSION 0)",BigDecimal.class,request.sourceId());var remaining=original.subtract(previous);if(remaining.signum()<=0)throw new ApiException(409,"ALREADY_COMPENSATED");return remaining;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public Map<String,Object> compensationQuote(Compensation request){validation.validate(request);var source=compensationSource(request);var amount=compensationAmount(request,source);return Map.of("source",json(source),"amount",amount.toPlainString(),"method",source.get("method"));}
    @Transactional(isolation=Isolation.SERIALIZABLE)
    public Map<String,Object> compensate(Compensation request,String key,long actor){validation.validate(request);settings.read(true,dates.today());String operation="COMPENSATION:"+actor;var existing=keys.read(operation,key,request);if(existing!=null)return existing;var source=compensationSource(request);Long admission=source.get("admissionId")==null?null:((Number)source.get("admissionId")).longValue();if(admission!=null)lockAdmission(admission);long session=cash.lockCurrent();var amount=compensationAmount(request,source);if(admission!=null&&net(admission).add(amount).signum()<0)throw new ApiException(409,"REFUND_EXCEEDS_NET");String kind=switch(request.sourceType()){case "EXPENSE"->"EXPENSE_COMPENSATION";case "REFUND"->"REFUND_COMPENSATION";default->"ADJUSTMENT_REVERSAL";};jdbc.update("INSERT dbo.Adjustment(cashSessionId,admissionId,expenseId,refundId,originalAdjustmentId,kind,method,amount,reason,actorId) VALUES(?,?,?,?,?,?,?,?,?,?)",session,admission,request.sourceType().equals("EXPENSE")?request.sourceId():null,request.sourceType().equals("REFUND")?request.sourceId():null,request.sourceType().equals("ADJUSTMENT")?request.sourceId():null,kind,source.get("method"),amount,request.reason().trim(),actor);var result=json(one("SELECT TOP(1) * FROM dbo.Adjustment WHERE cashSessionId=? ORDER BY id DESC",session));touch(session);keys.save(operation,key,request,result);return result;}
    private BigDecimal sum(List<Map<String,Object>> rows,String method){return rows.stream().filter(r->method==null||method.equals(r.get("method"))).map(r->new BigDecimal(r.get("amount").toString())).reduce(BigDecimal.ZERO.setScale(2),BigDecimal::add);}
    private Map<String,Object> currentSnapshot(Map<String,Object> session){
        long id=((Number)session.get("id")).longValue();var s=new LinkedHashMap<String,Object>();s.put("schemaVersion",2);s.put("cashSessionId",Long.toString(id));s.put("businessDate",session.get("businessDate").toString());s.put("timezone","America/Costa_Rica");s.put("currency","CRC");s.put("openingFloat",session.get("openingFloat").toString());
        var payments=rows("SELECT p.*,a.code,a.adultPrice,a.childPrice,a.seniorPrice,a.parkingPrice,d.visitDate,u.name actorName FROM dbo.Payment p JOIN dbo.Admission a ON a.id=p.admissionId JOIN dbo.VisitDay d ON d.id=a.visitDayId JOIN dbo.AppUser u ON u.id=p.actorId WHERE p.cashSessionId=? ORDER BY p.id",id);
        var expenses=rows("SELECT e.*,u.name actorName FROM dbo.Expense e JOIN dbo.AppUser u ON u.id=e.actorId WHERE e.cashSessionId=? ORDER BY e.id",id);
        var refunds=rows("SELECT r.*,a.code,d.visitDate,u.name actorName FROM dbo.Refund r JOIN dbo.Admission a ON a.id=r.admissionId JOIN dbo.VisitDay d ON d.id=a.visitDayId JOIN dbo.AppUser u ON u.id=r.actorId WHERE r.cashSessionId=? ORDER BY r.id",id);
        var adjustments=rows("SELECT a.*,u.name actorName,d.visitDate,g.code FROM dbo.Adjustment a JOIN dbo.AppUser u ON u.id=a.actorId LEFT JOIN dbo.Admission g ON g.id=a.admissionId LEFT JOIN dbo.VisitDay d ON d.id=g.visitDayId WHERE a.cashSessionId=? ORDER BY a.id",id);
        var attendance=rows("SELECT a.id,a.code,a.name,a.adults,a.children,a.seniors,a.vehicles,a.adultPrice,a.childPrice,a.seniorPrice,a.parkingPrice,a.reservationId,d.visitDate FROM dbo.Admission a JOIN dbo.VisitDay d ON d.id=a.visitDayId WHERE d.visitDate=? ORDER BY a.id",session.get("businessDate"));
        s.put("payments",payments);s.put("expenses",expenses);s.put("refunds",refunds);s.put("adjustments",adjustments);s.put("attendance",attendance);
        var totals=new LinkedHashMap<String,Object>();totals.put("payments",sum(payments,null).toPlainString());totals.put("expenses",sum(expenses,null).toPlainString());totals.put("refunds",sum(refunds,null).toPlainString());totals.put("adjustments",sum(adjustments,null).toPlainString());totals.put("additionalPayments",sum(adjustments.stream().filter(a->"ADDITIONAL_PAYMENT".equals(a.get("kind"))).toList(),null).toPlainString());totals.put("compensations",sum(adjustments.stream().filter(a->!"ADDITIONAL_PAYMENT".equals(a.get("kind"))).toList(),null).toPlainString());
        totals.put("operatingResult",sum(payments,null).add(sum(adjustments,null)).subtract(sum(expenses,null)).subtract(sum(refunds,null)).toPlainString());totals.put("expectedCash",new BigDecimal(s.get("openingFloat").toString()).add(sum(payments,"CASH")).add(sum(adjustments,"CASH")).subtract(sum(expenses,"CASH")).subtract(sum(refunds,"CASH")).toPlainString());
        for(String field:List.of("adults","children","seniors","vehicles"))totals.put(field,attendance.stream().mapToLong(a->((Number)a.get(field)).longValue()).sum());s.put("totals",totals);
        var methods=new ArrayList<Map<String,Object>>();for(String method:List.of("CASH","SINPE","CARD"))methods.add(Map.of("method",method,"payments",sum(payments,method).toPlainString(),"expenses",sum(expenses,method).toPlainString(),"refunds",sum(refunds,method).toPlainString(),"adjustments",sum(adjustments,method).toPlainString(),"net",sum(payments,method).add(sum(adjustments,method)).subtract(sum(expenses,method)).subtract(sum(refunds,method)).toPlainString()));s.put("methods",methods);return s;
    }
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public Map<String,Object> summary(LocalDate date){var sessions=jdbc.queryForList("SELECT * FROM dbo.CashSession WHERE businessDate=?",date);var result=new LinkedHashMap<String,Object>();result.put("serverDate",dates.today().toString());result.put("session",null);result.put("snapshot",null);result.put("closureId",null);if(sessions.isEmpty())return result;var session=sessions.getFirst();var closures=jdbc.queryForList("SELECT id FROM dbo.CashClosure WHERE cashSessionId=?",Long.class,session.get("id"));result.put("session",json(session));if(closures.isEmpty())result.put("snapshot",currentSnapshot(session));else{var c=closure(closures.getFirst());result.put("snapshot",c.get("snapshot"));result.put("closureId",c.get("id"));}return result;}
    @SuppressWarnings("unchecked")
    private void legacy(Map<String,Object> snapshot,Map<String,Object> row){if(snapshot.containsKey("totals"))return;snapshot.put("legacy",true);snapshot.put("timezone",snapshot.getOrDefault("timeZone","America/Costa_Rica"));snapshot.put("locale",row.get("locale"));snapshot.put("closedAt",((java.sql.Timestamp)row.get("createdAt")).toLocalDateTime().toInstant(ZoneOffset.UTC).toString());snapshot.put("actorId",row.get("actorId").toString());snapshot.put("actorName","ID "+row.get("actorId"));snapshot.put("recipient",row.get("recipient"));snapshot.put("note",row.get("note"));snapshot.put("businessName","");snapshot.put("cashSessionId",row.get("cashSessionId").toString());for(String field:List.of("countedCash","difference","openingFloat"))snapshot.put(field,new BigDecimal(snapshot.get(field).toString()).setScale(2).toPlainString());var totals=new LinkedHashMap<String,Object>();for(String section:List.of("payments","expenses","refunds","adjustments"))totals.put(section,sum((List<Map<String,Object>>)snapshot.get(section),null).toPlainString());totals.put("additionalPayments","0.00");totals.put("compensations",totals.get("adjustments"));for(String field:List.of("expectedCash","operatingResult"))totals.put(field,((BigDecimal)row.get(field)).toPlainString());for(String field:List.of("adults","children","seniors","vehicles"))totals.put(field,((List<Map<String,Object>>)snapshot.get("attendance")).stream().mapToLong(a->((Number)a.get(field)).longValue()).sum());snapshot.put("totals",totals);var methods=new ArrayList<Map<String,Object>>();for(String method:List.of("CASH","SINPE","CARD")){var m=new LinkedHashMap<String,Object>();m.put("method",method);for(String section:List.of("payments","expenses","refunds","adjustments"))m.put(section,sum((List<Map<String,Object>>)snapshot.get(section),method).toPlainString());m.put("net",new BigDecimal(m.get("payments").toString()).add(new BigDecimal(m.get("adjustments").toString())).subtract(new BigDecimal(m.get("expenses").toString())).subtract(new BigDecimal(m.get("refunds").toString())).toPlainString());methods.add(m);}snapshot.put("methods",methods);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public Map<String,Object> closure(long id){var row=one("SELECT * FROM dbo.CashClosure WHERE id=?",id);var result=json(row);var snapshot=mapper.readValue((String)row.get("snapshot"),new tools.jackson.core.type.TypeReference<LinkedHashMap<String,Object>>(){});legacy(snapshot,row);snapshot.put("closureId",Long.toString(id));result.put("snapshot",snapshot);var emails=rows("SELECT id,status,attempts,lastErrorCode FROM dbo.EmailOutbox WHERE eventType='CASH_CLOSED' AND eventId=?",id);result.put("email",emails.isEmpty()?null:emails.getFirst());return result;}
    @Transactional(isolation=Isolation.SERIALIZABLE)
    public Map<String,Object> close(long id,Close request,String key,long actor){
        validation.validate(request);var config=settings.read(true,dates.today());String operation="CLOSE:"+actor+":"+id;var replay=keys.read(operation,key,request);if(replay!=null)return replay;
        var session=one("SELECT * FROM dbo.CashSession WITH(UPDLOCK,HOLDLOCK) WHERE id=?",id);var previous=jdbc.queryForList("SELECT id FROM dbo.CashClosure WHERE cashSessionId=?",Long.class,id);if(!previous.isEmpty())return closure(previous.getFirst());if(!"OPEN".equals(session.get("status")))throw new ApiException(409,"CASH_SESSION_CLOSED");if(!request.version().equals(Base64.getEncoder().encodeToString((byte[])session.get("version"))))throw new ApiException(409,"VERSION_CONFLICT");
        var snapshot=currentSnapshot(session);var totals=(Map<?,?>)snapshot.get("totals");var counted=new BigDecimal(request.countedCash()).setScale(2);var expected=new BigDecimal(totals.get("expectedCash").toString());var difference=counted.subtract(expected);if(difference.signum()!=0&&(request.note()==null||request.note().isBlank()))throw new ApiException(400,"CLOSURE_NOTE_REQUIRED",Map.of("note","INVALID_FIELD"));
        var user=one("SELECT id,name,email FROM dbo.AppUser WHERE id=?",actor);String recipient=user.get("email").toString();if(recipient.isBlank())throw new ApiException(409,"ADMIN_EMAIL_REQUIRED");var closedAt=clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MILLIS);snapshot.put("closedAt",closedAt.toString());snapshot.put("locale",request.locale());snapshot.put("actorId",Long.toString(actor));snapshot.put("actorName",user.get("name"));snapshot.put("recipient",recipient);snapshot.put("countedCash",counted.toPlainString());snapshot.put("difference",difference.toPlainString());snapshot.put("note",request.note()==null?null:request.note().trim());snapshot.put("businessName",config==null?"":config.translations().stream().filter(t->t.locale().equals(request.locale())).findFirst().orElse(config.translations().getFirst()).displayName());
        jdbc.update("INSERT dbo.CashClosure(cashSessionId,countedCash,expectedCash,difference,operatingResult,note,snapshot,recipient,locale,actorId,createdAt) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,counted,expected,difference,new BigDecimal(totals.get("operatingResult").toString()),request.note(),mapper.writeValueAsString(snapshot),recipient,request.locale(),actor,LocalDateTime.ofInstant(closedAt,ZoneOffset.UTC));long closure=jdbc.queryForObject("SELECT id FROM dbo.CashClosure WHERE cashSessionId=?",Long.class,id);jdbc.update("UPDATE dbo.CashSession SET status='CLOSED' WHERE id=?",id);
        jdbc.update("INSERT dbo.EmailOutbox(eventType,eventId,eventVersion,recipient,locale,payload,messageId) VALUES('CASH_CLOSED',?,1,?,?,?,?)",closure,recipient,request.locale(),mapper.writeValueAsString(Map.of("closureId",Long.toString(closure),"businessDate",snapshot.get("businessDate"))),UUID.randomUUID()+"@tourism.local");event("CASH_CLOSED",closure,actor,"SUCCESS");var result=closure(closure);keys.save(operation,key,request,result);return result;
    }
    private void event(String type,long id,Long actor,String outcome){var context=com.tourism.business.audit.service.AuditContext.current();jdbc.update("INSERT dbo.ActivityEvent(eventType,entity,entityId,actorId,requestId,outcome) VALUES(?,'CashClosure',?,?,?,?)",type,id,actor,context==null?null:context.requestId().toString(),outcome);}
    @Transactional
    public void exported(long id,String format,long actor){event("REPORT_EXPORTED",id,actor,format.toUpperCase(Locale.ROOT));}
    @Transactional(isolation=Isolation.SERIALIZABLE)
    public Map<String,Object> retryEmail(long id){one("SELECT id FROM dbo.CashClosure WHERE id=?",id);var job=one("SELECT id,status FROM dbo.EmailOutbox WITH(UPDLOCK,HOLDLOCK) WHERE eventType='CASH_CLOSED' AND eventId=?",id);if("FAILED".equals(job.get("status"))){jdbc.update("UPDATE dbo.EmailOutbox SET status='PENDING',availableAt=SYSUTCDATETIME(),lockedAt=NULL,lastErrorCode=NULL WHERE id=?",job.get("id"));var context=com.tourism.business.audit.service.AuditContext.current();event("EMAIL_MANUAL_RETRY",id,context==null?null:context.actorId(),"QUEUED");}return closure(id);}
}
